import React, { useState, useCallback } from 'react';
import { useCanvasStore } from '@/store/canvas-store';
import { CanvasElement, ElementType } from '@/types/canvas-elements';
import { cn } from '@/lib/utils';

/**
 * PropertyPanel component props
 */
interface PropertyPanelProps {
  className?: string;
  elements?: Map<string, CanvasElement>; // Elements passed as prop (computed from slide data)
  onElementUpdate?: (elementId: string, updates: Partial<CanvasElement>) => void; // Callback for updates
}

/**
 * PropertyPanel - Dynamic property editor for canvas elements
 *
 * Phase 3 Update: Now receives elements as props instead of from canvas-store
 *
 * Features:
 * - Position controls (x, y)
 * - Size controls (width, height)
 * - Rotation control
 * - Opacity control
 * - Type-specific properties
 */
export const PropertyPanel: React.FC<PropertyPanelProps> = ({ className, elements, onElementUpdate }) => {
  const { selectedIds, setEditingElement } = useCanvasStore();

  // Get the first selected element (single select for now)
  const selectedElement = selectedIds.length === 1 && elements
    ? elements.get(selectedIds[0])
    : null;

  /**
   * Handle property change
   */
  const handleChange = useCallback((updates: Partial<CanvasElement>) => {
    if (!selectedElement || !onElementUpdate) return;
    onElementUpdate(selectedElement.id, updates);
  }, [selectedElement, onElementUpdate]);

  /**
   * Handle nested data property change
   */
  const handleDataChange = useCallback((
    key: string,
    value: any
  ) => {
    if (!selectedElement || !onElementUpdate) return;
    onElementUpdate(selectedElement.id, {
      data: {
        ...selectedElement.data,
        [key]: value,
      },
    });
  }, [selectedElement, onElementUpdate]);

  /**
   * Render no selection state
   */
  if (!selectedElement) {
    return (
      <div className={cn(
        'bg-black/20 backdrop-blur-xl border border-white/10 rounded-2xl p-6',
        'h-full flex items-center justify-center',
        className
      )}>
        <p className="text-white/50 text-sm">
          {selectedIds.length === 0
            ? 'Select an element to edit its properties'
            : `${selectedIds.length} elements selected\nProperties not available for multi-select`}
        </p>
      </div>
    );
  }

  return (
    <div className={cn(
      'bg-black/20 backdrop-blur-xl border border-white/10 rounded-2xl p-6',
      'h-full overflow-y-auto',
      className
    )}>
      {/* Element Header */}
      <div className="mb-6 pb-4 border-b border-white/10">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-white font-semibold text-lg">
              {selectedElement.name}
            </h3>
            <p className="text-white/50 text-sm capitalize">
              {selectedElement.type} Element
            </p>
          </div>
          <div className="flex items-center gap-2">
            {/* Lock Toggle */}
            <button
              onClick={() => handleChange({ locked: !selectedElement.locked })}
              className={cn(
                'p-2 rounded-lg transition-colors',
                selectedElement.locked
                  ? 'bg-yellow-500/20 text-yellow-400'
                  : 'bg-white/5 text-white/50 hover:bg-white/10'
              )}
              title={selectedElement.locked ? 'Unlock' : 'Lock'}
            >
              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                {selectedElement.locked ? (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
                ) : (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 11V7a4 4 0 118 0m-4 8v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
                )}
              </svg>
            </button>

            {/* Visibility Toggle */}
            <button
              onClick={() => handleChange({ visible: !selectedElement.visible })}
              className={cn(
                'p-2 rounded-lg transition-colors',
                selectedElement.visible
                  ? 'bg-white/5 text-white/50 hover:bg-white/10'
                  : 'bg-red-500/20 text-red-400'
              )}
              title={selectedElement.visible ? 'Hide' : 'Show'}
            >
              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                {selectedElement.visible ? (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                ) : (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l3.59 3.59m0 0A9.953 9.953 0 0112 5c4.478 0 8.268 2.943 9.543 7a10.025 10.025 0 01-4.132 5.411m0 0L21 21" />
                )}
              </svg>
            </button>
          </div>
        </div>
      </div>

      {/* Position Controls */}
      <div className="mb-6">
        <h4 className="text-white/70 text-sm font-medium mb-3">Position</h4>
        <div className="grid grid-cols-2 gap-3">
          <NumberInput
            label="X"
            value={selectedElement.x}
            onChange={(value) => handleChange({ x: value })}
            min={0}
            max={1080}
          />
          <NumberInput
            label="Y"
            value={selectedElement.y}
            onChange={(value) => handleChange({ y: value })}
            min={0}
            max={1350}
          />
        </div>
      </div>

      {/* Size Controls */}
      <div className="mb-6">
        <h4 className="text-white/70 text-sm font-medium mb-3">Size</h4>
        <div className="grid grid-cols-2 gap-3">
          <NumberInput
            label="Width"
            value={selectedElement.width}
            onChange={(value) => handleChange({ width: value })}
            min={10}
            max={1080}
          />
          <NumberInput
            label="Height"
            value={selectedElement.height}
            onChange={(value) => handleChange({ height: value })}
            min={10}
            max={1350}
          />
        </div>
      </div>

      {/* Rotation Control */}
      <div className="mb-6">
        <h4 className="text-white/70 text-sm font-medium mb-3">Rotation</h4>
        <div className="flex items-center gap-3">
          <SliderInput
            label="Angle"
            value={selectedElement.rotation}
            onChange={(value) => handleChange({ rotation: value })}
            min={0}
            max={360}
            step={1}
            unit="°"
          />
          <NumberInput
            label=""
            value={Math.round(selectedElement.rotation)}
            onChange={(value) => handleChange({ rotation: value })}
            min={0}
            max={360}
            step={1}
            unit="°"
            className="w-20"
          />
        </div>
      </div>

      {/* Opacity Control */}
      <div className="mb-6">
        <h4 className="text-white/70 text-sm font-medium mb-3">Opacity</h4>
        <div className="flex items-center gap-3">
          <SliderInput
            label="Opacity"
            value={selectedElement.opacity * 100}
            onChange={(value) => handleChange({ opacity: value / 100 })}
            min={0}
            max={100}
            step={1}
            unit="%"
          />
          <NumberInput
            label=""
            value={Math.round(selectedElement.opacity * 100)}
            onChange={(value) => handleChange({ opacity: value / 100 })}
            min={0}
            max={100}
            step={1}
            unit="%"
            className="w-20"
          />
        </div>
      </div>

      {/* Scale Controls */}
      <div className="mb-6">
        <h4 className="text-white/70 text-sm font-medium mb-3">Scale</h4>
        <div className="grid grid-cols-2 gap-3">
          <NumberInput
            label="Scale X"
            value={selectedElement.scaleX}
            onChange={(value) => handleChange({ scaleX: value })}
            min={0.1}
            max={5}
            step={0.1}
          />
          <NumberInput
            label="Scale Y"
            value={selectedElement.scaleY}
            onChange={(value) => handleChange({ scaleY: value })}
            min={0.1}
            max={5}
            step={0.1}
          />
        </div>
      </div>

      {/* Z-Index Control */}
      <div className="mb-6">
        <h4 className="text-white/70 text-sm font-medium mb-3">Layer</h4>
        <NumberInput
          label="Z-Index"
          value={selectedElement.zIndex}
          onChange={(value) => handleChange({ zIndex: value })}
          min={0}
          max={100}
        />
      </div>

      {/* Type-Specific Properties */}
      <TypeSpecificProperties
        element={selectedElement}
        onDataChange={handleDataChange}
      />
    </div>
  );
};

/**
 * Type-specific properties component
 */
interface TypeSpecificPropertiesProps {
  element: CanvasElement;
  onDataChange: (key: string, value: any) => void;
}

const TypeSpecificProperties: React.FC<TypeSpecificPropertiesProps> = ({
  element,
  onDataChange,
}) => {
  switch (element.type) {
    case 'text':
      return <TextProperties element={element} onDataChange={onDataChange} />;
    case 'image':
      return <ImageProperties element={element} onDataChange={onDataChange} />;
    case 'background':
      return <BackgroundProperties element={element} onDataChange={onDataChange} />;
    case 'cta':
      return <CTAProperties element={element} onDataChange={onDataChange} />;
    case 'shape':
      return <ShapeProperties element={element} onDataChange={onDataChange} />;
    case 'decorator':
      return <DecoratorProperties element={element} onDataChange={onDataChange} />;
    default:
      return null;
  }
};

